from itertools import combinations

# Interpretation: each subject needs its stated number of DISTINCT teachers
# (a teacher teaches a subject at most once), and each teacher teaches at most 4 subjects.
REQ = {"maths": 6, "physics": 5, "chemistry": 5}
MAX_SUBJECTS_PER_TEACHER = 4
SUBJECTS = list(REQ)


def find_assignment(n):
    """Exhaustively search for n teachers covering every subject's requirement.
    Returns a witness dict {subject: set_of_teachers} or None."""
    if any(r > n for r in REQ.values()):
        return None  # a subject with r slots needs r distinct teachers
    pools = [combinations(range(n), REQ[s]) for s in SUBJECTS]
    # Enumerate every choice of teacher-subsets for each subject.
    all_choices = [list(combinations(range(n), REQ[s])) for s in SUBJECTS]
    for m in all_choices[0]:
        for p in all_choices[1]:
            for c in all_choices[2]:
                load = [0] * n
                for group in (m, p, c):
                    for t in group:
                        load[t] += 1
                if max(load) <= MAX_SUBJECTS_PER_TEACHER:
                    return {"maths": set(m), "physics": set(p), "chemistry": set(c)}
    return None


def verify_witness(n, w):
    """Independently check the witness: exact subject counts and load limits."""
    for s in SUBJECTS:
        if len(w[s]) != REQ[s]:
            return False
        if not all(0 <= t < n for t in w[s]):
            return False
    load = [sum(t in w[s] for s in SUBJECTS) for t in range(n)]
    return max(load) <= MAX_SUBJECTS_PER_TEACHER


total_slots = sum(REQ.values())
naive_bound = -(-total_slots // MAX_SUBJECTS_PER_TEACHER)  # ceil(16/4)
print(f"Total teaching slots = {total_slots}")
print(f"Naive bound ceil(slots/4) = {naive_bound} (ignores distinctness; not the answer)")
print(f"Largest per-subject requirement = {max(REQ.values())} (distinct teachers needed)")

minimum = None
witness = None
for n in range(1, 13):
    w = find_assignment(n)
    if w is not None:
        minimum, witness = n, w
        break

if minimum is None:
    print("UNSUPPORTED: no feasible n found in search range")
else:
    print(f"Minimum teachers found by exhaustive search = {minimum}")
    for s in SUBJECTS:
        print(f"  {s}: teachers {sorted(witness[s])}")
    ok = verify_witness(minimum, witness)
    print("Witness verification:", "CHECK PASS" if ok else "CHECK FAIL")

    # Confirm n-1 is infeasible (completeness of the minimum).
    below = find_assignment(minimum - 1) if minimum > 1 else None
    print(f"Feasible with {minimum - 1} teachers: {below is not None}")

submitted = 4
if minimum is None:
